// Render-props pattern: DataList owns no presentation, only iteration.
// It predates hooks as the standard way to share behavior, and still
// shows up in teaching material for contrast — today a custom hook
// (e.g. useFilteredList) would usually replace this, but render props
// remain useful when the *markup*, not just the data, must be injected
// by the caller.
export function DataList({ items, empty = null, render }) {
  if (!items || items.length === 0) return empty;
  return <>{items.map((item) => render(item))}</>;
}
